import { useAuth, useUiState, useAppState } from '../lib/store';
import { apiClient, StatusWebSocket } from '../lib/api';
import { Sidebar } from './Sidebar';
import { DashboardContent } from './DashboardContent';
import { JobsContent } from './JobsContent';
import { SettingsContent } from './SettingsContent';
import { StatsContent } from './StatsContent';

export function Dashboard() {
  const { token } = useAuth();
  const { activeTab } = useUiState();
  const { setStatus, setError } = useAppState();

  // Set token in API client
  useEffect(() => {
    if (token) {
      apiClient.setToken(token);
    }
  }, [token]);

  // Fetch initial status
  const { data: statusData, error: statusError } = useQuery({
    queryKey: ['status'],
    queryFn: () => apiClient.getStatus(),
    refetchInterval: 30000, // Refetch every 30 seconds
    enabled: !!token,
  });

  // Update status when data changes
  useEffect(() => {
    if (statusData?.data) {
      setStatus(statusData.data);
    }
  }, [statusData, setStatus]);

  // Handle status errors
  useEffect(() => {
    if (statusError) {
      setError(statusError.message || 'Failed to fetch status');
    }
  }, [statusError, setError]);

  // WebSocket connection for real-time updates
  useEffect(() => {
    if (!token) return;

    const ws = new StatusWebSocket(
      (data) => {
        setStatus(data);
      },
      (error) => {
        console.error('WebSocket error:', error);
        setError('WebSocket connection error');
      },
      () => {
        console.log('WebSocket disconnected');
      }
    );

    ws.setToken(token);
    ws.connect();

    return () => {
      ws.disconnect();
    };
  }, [token, setStatus, setError]);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <DashboardContent />;
      case 'jobs':
        return <JobsContent />;
      case 'settings':
        return <SettingsContent />;
      case 'stats':
        return <StatsContent />;
      default:
        return <DashboardContent />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      <div className="flex">
        <Sidebar />
        <main className="flex-1 overflow-auto">
          <div className="p-6">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
}"}

